    cover: 'https://imgapixs.pysmei.com/bookfiles/bookimages/' + decrypt(data.Img),
    desc: decrypt(data.Desc),
    author: decrypt(data.Author),
    category: decrypt(data.CName),
    status: decrypt(data.BookStatus),
